#requires -Version 5.1
# Generated by Prepare-Package.ps1. Upload the generated Detect-Installation.ps1 to Intune.
$ErrorActionPreference='Stop'
$ExpectedManifestHash='__MANIFEST_SHA256__'
try {
    $root=Join-Path ([Environment]::GetFolderPath('CommonApplicationData')) 'ClaudePolicyManager'
    $manifestPath=Join-Path $root 'PackageManifest.json'
    if ((Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256).Hash.ToLowerInvariant() -cne $ExpectedManifestHash) {throw 'Assigned package/configuration differs.'}
    $manifest=Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json
    $modulePath=Join-Path $root 'PolicyEngine.psm1'
    if ((Get-FileHash -LiteralPath $modulePath -Algorithm SHA256).Hash.ToLowerInvariant() -cne $manifest.Files.'PolicyEngine.psm1') {throw 'Engine missing or altered.'}
    Import-Module $modulePath -Force -DisableNameChecking
    Assert-InstallationHealthy $root
    Write-Output "Detected Claude policy manager: $($manifest.ConfigurationId)."
    exit 0
} catch {
    # Intune: exit 1 means not detected. No success output is emitted on failure.
    exit 1
}
